// ********************************************************************************************
// ********************************************************************************************

int CCodes::get_state_name(int ndx, std::string &name)
{
	if ((ndx < 0) || (ndx >= CODES_NUM_STATES))
		return FAILURE;

	name = state_codes[ndx].name;

	return SUCCESS;
}

// ********************************************************************************************
// ********************************************************************************************

int CCodes::get_fips_code_from_name(std::string name, int *fipscode)
{
	int k;
	std::string test;
	BOOL found = FALSE;

	if (name.length() < 4)
		return FAILURE;

	k = 0;
	while (!found && (k < CODES_NUM_STATES))
	{
		test = state_codes[k].name;
		if (!test.compare(name))
		{
			*fipscode = state_codes[k].fips_code;
			found = TRUE;
			continue;
		}
		k++;
	}

	if (found)
		return SUCCESS;
	else
		return FAILURE;
}

// ********************************************************************************************
// ********************************************************************************************

int CCodes::get_name_from_fips_code(int fipscode, std::string &name)
{
	int k;
	BOOL found = FALSE;

	k = 0;
	while (!found && (k < CODES_NUM_STATES))
	{
		if (fipscode == state_codes[k].fips_code)
		{
			name = state_codes[k].name;
			found = TRUE;
			continue;
		}
		k++;
	}

	if (found)
		return SUCCESS;
	else
		return FAILURE;
}

// ********************************************************************************************
// ********************************************************************************************

int CCodes::get_geotiff_utm_zone_name(int ndx, std::string &name)
{
	if ((ndx < 0) || (ndx >= CODES_NUM_GEOTIFF_UTM_ZONE))
		return FAILURE;

	name = geotiff_utm_zone[ndx].name;

	return SUCCESS;
}

// ********************************************************************************************
// ********************************************************************************************

int CCodes::get_geotiff_utm_zone_from_name(std::string name, int *utm_zone)
{
	int k;
	std::string test;
	BOOL found = FALSE;

	if (name.length() < 4)
		return FAILURE;

	k = 0;
	while (!found && (k < CODES_NUM_GEOTIFF_UTM_ZONE))
	{
		test = geotiff_utm_zone[k].name;
		if (!test.compare(name))
		{
			*utm_zone = geotiff_utm_zone[k].geotiff_utm_zone;
			found = TRUE;
			continue;
		}
		k++;
	}

	if (found)
		return SUCCESS;
	else
		return FAILURE;
}

