// ********************************************************************************************

int CCodes::get_sp_geotiff_code_from_name(std::string name, int *geotiff_code, int *units)
{
	int k;
	BOOL found = FALSE;
	std::string tstr, key;

	key = name;
//	key.TrimRight();

	k = 0;
	while ((k<CODES_NUM_SP_CODES) && !found)
	{
		tstr = state_plane_code[k].name;
//		tstr.TrimRight();
		if (!key.compare(tstr))
		{
			*geotiff_code = state_plane_code[k].geotiff_code;
			*units = state_plane_code[k].units;
			found = TRUE;
			continue;
		}
		k++;
	}

	if (found)
		return SUCCESS;
	else
		return FAILURE;
}

