int CCodes::geotiff_to_fips(long geotiff_code, long *fips_zone, long *datum)
{
	int k;
	BOOL found = FALSE;

	k = 0;
	while ((k<CODES_NUM_SP_CODES) && !found)
	{
		if (geotiff_code == state_plane_code[k].geotiff_code)
		{
			*fips_zone = state_plane_code[k].fips_zone;
			*datum = state_plane_code[k].datum;
			found = TRUE;
			continue;
		}
		k++;
	}

	if (found)
		return SUCCESS;
	else
		return FAILURE;
}

