// ********************************************************************************************

int CCodes::fips_to_geotiff(int fips_zone, int datum, int *geotiff_code)
{
	int k;
	BOOL found = FALSE;

	k = 0;
	while ((k<CODES_NUM_SP_CODES) && !found)
	{
		if ((fips_zone == state_plane_code[k].fips_zone) && (datum == state_plane_code[k].datum))
		{
			*geotiff_code = state_plane_code[k].geotiff_code;
			found = TRUE;
			continue;
		}
		k++;
	}

	if (found)
		return SUCCESS;
	else
		return FAILURE;
}

// ********************************************************************************************
// ********************************************************************************************

int CCodes::get_next_field(char *input, int *pos, std::string & data)
{
	char buf[100], ch;
	int cnt, len;
	BOOL notdone;

	len = strlen(input);
	if (*pos >= len)
		return FAILURE;

	cnt = 0;
	notdone = TRUE;
	while (notdone)
	{
		ch = input[*pos];
		if (ch == ',')
		{
			notdone = FALSE;
			continue;
		}
		buf[cnt] = ch;
		if (*pos >= len)
		{
			notdone = FALSE;
			continue;
		}
		(*pos)++;
		cnt++;
	}

	buf[cnt] = '\0';
	data = buf;

	return SUCCESS;
}

// ********************************************************************************************
// ********************************************************************************************

//COUNTY_NAME,TYPE,STATE,STATE_ABBREVIATION,SPC27,SPC83,STFIPS,COFIPS,FIPS,LATITUDE,LONGITUDE,UTM

int CCodes::decode_county(int ndx, std::string &county_name, std::string &county_type, std::string &state_name,
				  std::string &state_abbrev, int *spc27, int *spc83, int *state_fips,
				  int *county_fips, int *fips, double *lat, double *lon, int *utm_zone)
{
   const rsize_t cty_len = 104;
	char cty[cty_len];
	int pos;
//	int rslt;
	std::string data;

	if ((ndx < 0) || (ndx > CODES_COUNTY_NUM))
		return FAILURE;

	strcpy_s(cty, cty_len, county[ndx]);
	pos = 0;

	get_next_field(cty, &pos, data);
	county_name = data;
	pos++;

	get_next_field(cty, &pos, data);
	county_type = data;
	pos++;

	get_next_field(cty, &pos, data);
	state_name = data;
	pos++;

	get_next_field(cty, &pos, data);
	state_abbrev = data;
	pos++;

	get_next_field(cty, &pos, data);
	*spc27 = atoi(data.c_str());
	pos++;

	get_next_field(cty, &pos, data);
	*spc83 = atoi(data.c_str());
	pos++;

	get_next_field(cty, &pos, data);
	*state_fips = atoi(data.c_str());
	pos++;

	get_next_field(cty, &pos, data);
	*county_fips = atoi(data.c_str());
	pos++;

	get_next_field(cty, &pos, data);
	*fips = atoi(data.c_str());
	pos++;

	get_next_field(cty, &pos, data);
	*lat = atof(data.c_str());
	pos++;

	get_next_field(cty, &pos, data);
	*lon = atof(data.c_str());
	pos++;

	get_next_field(cty, &pos, data);
	*utm_zone = atoi(data.c_str());

	return SUCCESS;
}
// end of decode_county